package com.mhtextractor.gui.controller;

import com.mhtextractor.model.ExtractionStats;
import com.mhtextractor.i18n.Texts;
import com.mhtextractor.uicore.WorkspaceView;
import com.mhtextractor.model.AppConfig;
import com.mhtextractor.uicore.PreviewRow;
import com.mhtextractor.model.ExtractOutcome;
import com.mhtextractor.uicore.GroupRow;
import javafx.scene.control.Label;
import javafx.scene.control.TextField;
import javafx.scene.layout.HBox;
import lombok.extern.slf4j.Slf4j;

import java.util.List;

/**
 * 工作区信息呈现协作者（C5）：模式摘要 / 选中信息区 / 提取结果展示从 {@code MainController}
 * <b>原样外迁</b> —— 文案键（preview.* / extract.* / list.colon / list.itemSeparator）、
 * 日志键（仍是 {@code log.maincontroller.29}，键名、实参与调用次数不变）、
 * 组条目编辑框接线（经 {@link Host#attachGroupNameEditor} 与 {@link Host#clearNameEditingGroup}）全部保持不变。
 *
 * <p>宿主能力经 {@link Host} 收窄为具名方法：本类不持有 {@code MainController} / {@code MainViewRefs} /
 * FXML namespace，也不得在数据序上直写（结果回写只改 {@link PreviewRow} 的
 * {@code extractOutcome / extractMessageKey/Params/Detail / extractWarnings} 字段）。</p>
 *
 * <p>本类含 JavaFX，属 {@code gui} 层。</p>
 */
@Slf4j
public final class WorkspaceInfoPresenter {

    /** GUI rendering of language-neutral port errors, in the original concatenation order. */
    static String errorText(PreviewRow row) {
        return row.errorKey == null ? "" : Texts.get(row.errorKey) + row.errorDetail;
    }

    static String detailText(String key, java.util.Map<String, String> params) {
        if (key == null) return null;
        Object[] args = params == null ? new Object[0] : params.entrySet().stream()
                .flatMap(e -> java.util.stream.Stream.of(e.getKey(), e.getValue())).toArray();
        return Texts.get(key, args);
    }

    /**
     * 宿主能力面（C5）：对 {@code MainController} 的全部能力需求收窄为具名方法。
     * 实现由 {@code MainController} 的匿名内部类提供（转发到其保留成员）。
     */
    public interface Host {
        Label titleInfoLabel();                          // = refs.titleInfoLabel()
        HBox titleEditBox();                             // = refs.titleEditBox()
        TextField titleField();                          // = refs.titleField()
        Label outputNameLabel();                         // = refs.outputNameLabel()
        HBox groupNameBox();                             // = refs.groupNameBox()
        Label badgeHeaderLabel();                        // = refs.badgeHeaderLabel()
        Label outputModeLabel();                         // = refs.outputModeLabel()
        Label extractResultBanner();                     // = refs.extractResultBanner()
        TextField inputFolderField();                    // = refs.inputFolderField()
        AppConfig effectiveParams(Object item);          // = effectiveForObject(item)
        AppConfig currentParamsOrDefaults();             // = currentParamsOrDefaults()
        boolean isTextMode();                            // = isTextMode()
        List<PreviewRow> allVisibleItems();             // = allVisibleItems()
        List<PreviewRow> allPreviewItems();             // = allPreviewItems()
        Object currentSelection();                       // = refs.fileListView().getSelectionModel().getSelectedItem()
        void refreshList();                              // = refs.fileListView().refresh()
        void attachGroupNameEditor(GroupRow<PreviewRow> group); // = attachGroupNameEditor(group)
        void clearNameEditingGroup();                    // = nameEditingGroup = null
        void attachTitleEditor(PreviewRow item);        // = attachTitleEditor(item)
        void clearTitleEditingItem();                    // = titleEditingItem = null
    }

    private final Host host;

    public WorkspaceInfoPresenter(Host host) {
        this.host = host;
    }

    void updateInfoArea(Object item) {
        updateExtractBanner(item);
        // 组条目：第二行（原"输出文件："位置）变为"输出组文件名："+ 可编辑输入框（F5 6.3）
        if (item instanceof GroupRow<?> g) {
            host.titleInfoLabel().setVisible(false);
            host.titleInfoLabel().setManaged(false);
            host.titleEditBox().setVisible(false);
            host.titleEditBox().setManaged(false);
            host.clearTitleEditingItem();
            host.outputNameLabel().setVisible(false);
            host.outputNameLabel().setManaged(false);
            host.groupNameBox().setVisible(true);
            host.groupNameBox().setManaged(true);
            host.attachGroupNameEditor(WorkspaceView.asPreviewGroup(g));
            return;
        }
        AppConfig params = host.effectiveParams(item);
        boolean confirmed = params != null;
        if (params == null) {
            params = new AppConfig();
        }
        host.clearNameEditingGroup();
        host.groupNameBox().setVisible(false);
        host.groupNameBox().setManaged(false);
        // 提取标题行：文本模式 + 标题提取开启且起始标记非空时显示（与正式提取判定一致，按该条目生效参数）
        boolean showTitle = confirmed && host.isTextMode() && params.isEnableTitleExtraction()
                && params.getTitleStartMarker() != null && !params.getTitleStartMarker().isEmpty();
        // 需求（提取标题可编辑）：showTitle 且条目已就绪（READY）时，把只读标题行换成可编辑文本框；
        // 解析中 / 无标题 / 非条目等其余情况保持原只读展示。
        PreviewRow readyItem = item instanceof PreviewRow pi && pi.status == PreviewRow.Status.READY
                ? pi : null;
        boolean editableTitle = showTitle && readyItem != null;
        host.titleEditBox().setVisible(editableTitle);
        host.titleEditBox().setManaged(editableTitle);
        host.titleInfoLabel().setVisible(showTitle && !editableTitle);
        host.titleInfoLabel().setManaged(showTitle && !editableTitle);
        if (!editableTitle) {
            host.clearTitleEditingItem();
        }
        if (!(item instanceof PreviewRow it) || !confirmed) {
            host.outputNameLabel().setVisible(false);
            host.outputNameLabel().setManaged(false);
            return;
        }
        if (editableTitle) {
            host.attachTitleEditor(readyItem);
        } else if (showTitle) {
            switch (it.status) {
                case WAITING -> host.titleInfoLabel().setText(Texts.get("preview.titleParsing"));
                case FAILED, EMPTY -> host.titleInfoLabel().setText(Texts.get("preview.titleNone"));
                case READY -> host.titleInfoLabel().setText(it.cachedTitle != null
                        ? Texts.get("preview.titlePrefix") + it.cachedTitle
                        : Texts.get("preview.titleNotFound"));
            }
        }
        host.outputNameLabel().setVisible(true);
        host.outputNameLabel().setManaged(true);
        if (host.isTextMode()) {
            String outputName = it.displayName == null ? Texts.get("preview.parsing") : it.displayName;
            if (params.isSeparateFiles()) {
                host.outputNameLabel().setText(Texts.get("preview.outputFilePrefix") + outputName);
            } else {
                host.outputNameLabel().setText(Texts.get("preview.outputFilePrefix") + outputName
                        + Texts.get("preview.outputFileTxtSuffix"));
            }
        } else {
            String dirName = it.displayName == null ? Texts.get("preview.parsing") : it.displayName;
            if (params.isSingleOutputMode()) {
                host.outputNameLabel().setText(Texts.get("preview.outputDirPrefix") + dirName
                        + Texts.get("preview.outputDirMergedNote"));
            } else {
                host.outputNameLabel().setText(Texts.get("preview.outputDirPrefix") + dirName);
            }
        }
    }

    /** 输出模式标签按当前选中对象的生效参数显示（组条目→该组生效参数；项目→其生效参数；无选中→全局） */
    void updateOutputModeLabel(Object sel) {
        AppConfig params = host.effectiveParams(sel);
        if (params == null) {
            params = host.currentParamsOrDefaults();
        }
        host.outputModeLabel().setText(host.isTextMode()
                ? (params.isSeparateFiles() ? Texts.get("extract.outputModeSeparate") : Texts.get("extract.outputModeMerged"))
                : (params.isSingleOutputMode() ? Texts.get("extract.outputModeMerged") : Texts.get("extract.outputModeSeparate")));
    }

    void updateBadgeHeader() {
        boolean showBadgeCol = host.isTextMode() && anyVisibleItemHasChapterNumbers();
        host.badgeHeaderLabel().setVisible(showBadgeCol);
        host.badgeHeaderLabel().setManaged(showBadgeCol);
    }

    /** 任一有效项目的生效参数开启章节序号（组参数可独立开启，列头按需显示） */
    private boolean anyVisibleItemHasChapterNumbers() {
        for (PreviewRow it : host.allVisibleItems()) {
            AppConfig eff = host.effectiveParams(it);
            if (eff != null && eff.isAddChapterNumber()) {
                return true;
            }
        }
        return false;
    }

    /** 提取结果一次性回写（拍板：提取结束/取消后统一回写，非逐文件实时更新）：
     *  按路径匹配条目读取端口结果事实，列表一次刷新，选中条目 banner 同步 */
    void applyExtractResults(ExtractionStats stats) {
        long matched = host.allPreviewItems().stream().filter(item -> item.extractOutcome != ExtractOutcome.NONE).count();
        host.refreshList();
        updateExtractBanner(host.currentSelection());
        log.info(Texts.msg("log.maincontroller.29", matched));
    }

    /** 提取结果色清除（拍板）：重新确认参数后旧结果失效，回到参数色/解析状态色 */
    void clearExtractOutcomes(List<PreviewRow> targets) {
        for (PreviewRow it : targets) {
            it.extractOutcome = ExtractOutcome.NONE;
            it.extractMessageKey = null;
            it.extractMessageParams = null;
            it.extractMessageDetail = null;
            it.extractWarnings = java.util.List.of();
        }
    }

    /** 预览区顶部 banner（拍板）：选中条目结果含红（失败/跳过/成功+警告）时显示具体情况；
     *  无提取结果时，解析失败（黄色）条目显示解析失败原因 */
    void updateExtractBanner(Object sel) {
        String detail = sel instanceof PreviewRow row ? Texts.extractDetail(row.extractMessageKey,
                row.extractMessageParams, row.extractMessageDetail, row.extractWarnings) : null;
        if (sel instanceof PreviewRow it && it.extractOutcome != ExtractOutcome.NONE
                && detail != null && !detail.isEmpty()) {
            String prefix = switch (it.extractOutcome) {
                case FAILED -> Texts.get("extract.statusFailed");
                case SKIPPED -> Texts.get("extract.statusSkipped");
                case SUCCESS_WARNED -> Texts.get("extract.statusWarned");
                default -> null;
            };
            if (prefix != null) {
                host.extractResultBanner().setText(prefix + Texts.get("list.colon") + detail);
                host.extractResultBanner().setVisible(true);
                host.extractResultBanner().setManaged(true);
                return;
            }
        }
        if (sel instanceof PreviewRow it && it.status == PreviewRow.Status.FAILED) {
            host.extractResultBanner().setText(Texts.get("extract.parseFailed") + WorkspaceInfoPresenter.errorText(it));
            host.extractResultBanner().setVisible(true);
            host.extractResultBanner().setManaged(true);
            return;
        }
        host.extractResultBanner().setVisible(false);
        host.extractResultBanner().setManaged(false);
    }
}
package com.mhtextractor.uicore;

import com.mhtextractor.model.AppConfig;
import com.mhtextractor.model.ChangeListener;
import com.mhtextractor.model.ExtractOutcome;
import com.mhtextractor.model.ThumbnailData;
import com.mhtextractor.uicore.ParamTargetView;
import com.mhtextractor.uiport.*;
import java.time.LocalDateTime;
import java.util.*;
import java.util.function.Consumer;

/** Stable-ID display row. These values are replaced from backend VMs, never used as a business model. */
public final class PreviewRow implements ParamTargetView {
    public enum Status{WAITING,READY,EMPTY,FAILED}
    public final String path,name,sourceFolder;
    public final LocalDateTime modifiedTime;
    public Status status=Status.WAITING;
    public String errorKey,errorDetail,badge,cachedText,cachedTitle,titleOverride;
    public String extractMessageKey, extractMessageDetail;
    public java.util.Map<String, String> extractMessageParams;
    public java.util.List<com.mhtextractor.model.ExtractWarning> extractWarnings = java.util.List.of();

    public boolean chapterEnabled,selected,removed;
    public ExtractOutcome extractOutcome=ExtractOutcome.NONE;
    public GroupRow<PreviewRow> parentGroup;
    private ParameterStateVm.TargetState textState,imageState;
    public List<ThumbnailData> cachedThumbs;
    public List<PortEvent.ImageFile> cachedImages;
    public PresentationVm cachedMeta;
    public boolean previewCached;
    public String previewHead="",previewTail="",displayName;
    private final Consumer<Boolean> check;
    private final PreviewRetention retention;
    private final List<ChangeListener> checkedListeners=new ArrayList<>();
    public PreviewRow(ItemVm vm,Consumer<Boolean> check){
        this(vm,check,new PreviewRetention());
    }
    PreviewRow(ItemVm vm,Consumer<Boolean> check,PreviewRetention retention){
        this.retention=retention;
        this.path=vm.id();name=vm.name();sourceFolder=vm.sourceFolder();
        modifiedTime=vm.modifiedTime()==null?null:LocalDateTime.parse(vm.modifiedTime());this.check=check;update(vm);
    }
    void update(ItemVm vm){
        boolean changed=selected!=vm.checked();selected=vm.checked();removed=vm.removed();
        status=vm.status()==null?Status.WAITING:Status.valueOf(vm.status());errorKey=vm.errorKey();errorDetail=vm.errorDetail();
        chapterEnabled=Boolean.TRUE.equals(vm.chapterEnabled());badge=vm.badge();cachedTitle=vm.cachedTitle();titleOverride=vm.titleOverride();
        boolean hadPreview=previewCached;previewCached=vm.previewManifest()!=null;
        if(hadPreview&&!previewCached){releaseImageData();cachedMeta=null;}
        extractOutcome=vm.extractOutcome()==null?ExtractOutcome.NONE:ExtractOutcome.valueOf(vm.extractOutcome());extractMessageKey=vm.extractMessageKey();extractMessageParams=vm.extractMessageParams();
        extractMessageDetail=vm.extractMessageDetail();extractWarnings=vm.extractWarnings();
        if(changed)for(var listener:List.copyOf(checkedListeners))listener.onValueChanged();
    }
    public TargetId id(){return TargetId.ofItem(path);}
    public String getName(){return name;}
    public AppConfig getTextParamsCache(){return parentGroup==null&&textState!=null&&textState.independent()?textState.config():null;}
    public AppConfig getImageParamsCache(){return parentGroup==null&&imageState!=null&&imageState.independent()?imageState.config():null;}
    void parameters(boolean image,ParameterStateVm.TargetState state){if(image)imageState=state;else textState=state;}
    public void addSelectedChangeListener(ChangeListener l){checkedListeners.add(l);}
    public void removeSelectedChangeListener(ChangeListener l){checkedListeners.remove(l);}
    public void setSelected(boolean value){check.accept(value);}
    public void retainImageData(){retention.retain(this);}
    public void releaseImageData(){retention.forget(this);cachedThumbs=null;cachedImages=null;}
    public void resetPreviewState(){releaseImageData();cachedMeta=null;cachedText=null;}
}
package com.mhtextractor.uicore;
import com.mhtextractor.uicore.FrontendPort;
import com.mhtextractor.uicore.PortSnapshot;
import com.mhtextractor.uiport.*;
import java.util.*;
/** Materializes display identities from a complete VM snapshot. No domain objects or undo stack. */
public final class WorkspaceView {
    private final FrontendPort port;
    private final java.util.function.LongFunction<String> defaultGroupName;
    private final PreviewRetention previewRetention=new PreviewRetention();
    private final Map<String,PreviewRow> items=new LinkedHashMap<>();
    private final Map<Long,GroupRow<PreviewRow>> groups=new LinkedHashMap<>();
    private List<Object> order=List.of();
    private long version;
    private final AutoCloseable subscription;
    public WorkspaceView(FrontendPort port, java.util.function.LongFunction<String> defaultGroupName){this.defaultGroupName=defaultGroupName;this.port=port;update(port.snapshot());subscription=port.events().subscribe(ignored->update(port.snapshot()));}
    public void update(PortSnapshot state){
        var vm=state.workspace();
        var active=new HashSet<String>();var topActive=new HashSet<String>();
        var current=new LinkedHashMap<String,ItemVm>();
        for(var g:vm.groups())for(var i:g.members())current.merge(i.id(),i,(old,next)->old.removed()&&!next.removed()?next:old);
        for(var i:vm.topLevelItems()){current.merge(i.id(),i,(old,next)->old.removed()&&!next.removed()?next:old);if(!i.removed())topActive.add(i.id());}
        current.values().forEach(i->{item(i);if(!i.removed())active.add(i.id());});
        for(var row:items.values())row.parentGroup=null;
        for(var g:vm.groups()){
            var row=groups.computeIfAbsent(g.no(),ignored->new GroupRow<>(g, defaultGroupName));
            var members=g.members().stream().filter(i->!i.removed()||!active.contains(i.id())).map(i->items.get(i.id())).toList();row.update(g,members);
            for(var member:members)member.parentGroup=row;
        }
        for(var mode:List.of(false,true))for(var target:state.parameters(mode).states()){
            if(target.target().groupNo()!=null)groups.get(target.target().groupNo()).parameters(mode,target);
            else items.get(target.target().path()).parameters(mode,target);
        }
        for(var entry:state.presentation()){
            var row=items.get(entry.path());row.cachedText=state.textBodies().get(entry.path());
            row.previewHead=entry.head();row.previewTail=entry.tail();row.displayName=entry.displayName();
            row.cachedMeta=row.previewCached?entry:null;row.cachedImages=entry.images();
        }
        var last=new HashMap<TargetId,Integer>();
        for(int index=0;index<vm.topLevelOrder().size();index++)last.put(vm.topLevelOrder().get(index),index);
        order=java.util.stream.IntStream.range(0,vm.topLevelOrder().size()).filter(index->{
            var id=vm.topLevelOrder().get(index);return last.get(id)==index
                    &&(id.groupNo()!=null||!active.contains(id.path())||topActive.contains(id.path()));
        }).mapToObj(index->{var id=vm.topLevelOrder().get(index);return id.groupNo()==null?(Object)items.get(id.path()):groups.get(id.groupNo());}).toList();
        version++;
    }
    private PreviewRow item(ItemVm vm){var row=items.computeIfAbsent(vm.id(),id->new PreviewRow(vm,value->port.commands().setChecked(List.of(id),value),previewRetention));row.update(vm);return row;}
    public List<Object> topLevel(){return order;}
    public List<Object> topLevelView(){return order;}
    public List<PreviewRow> allItems(){return order.stream().flatMap(o->o instanceof GroupRow<?> g?g.getMembers().stream().map(PreviewRow.class::cast):java.util.stream.Stream.of((PreviewRow)o)).toList();}
    public List<GroupRow<PreviewRow>> groups(){return order.stream().filter(GroupRow.class::isInstance).map(o->asPreviewGroup((GroupRow<?>)o)).toList();}
    public List<Object> displayOrder(){var list=new ArrayList<Object>();for(var o:order){if(o instanceof GroupRow<?> g){list.add(g);if(g.isExpanded())for(var member:g.getMembers())if(!((PreviewRow)member).removed)list.add(member);}else if(!((PreviewRow)o).removed)list.add(o);}return List.copyOf(list);}
    public long visibleCount(){return allItems().stream().filter(i->!i.removed).count();}
    public boolean canUndo(){return port.queries().workspace().canUndo();}
    public long version(){return version;}
    public PortSnapshot snapshot(){return port.snapshot();}
    public AutoCloseable subscribe(java.util.function.Consumer<PortEvent.WorkspaceChanged> listener){
        return port.events().subscribe(event->{if(event instanceof PortEvent.WorkspaceChanged change)listener.accept(change);});
    }
    public void dispose(){try{subscription.close();}catch(Exception error){throw new IllegalStateException(error);}}
    public void clearItems(){port.commands().clearItems();}
    @SuppressWarnings("unchecked") public static GroupRow<PreviewRow> asPreviewGroup(GroupRow<?> group){return (GroupRow<PreviewRow>)group;}
}
